const { price } = require("./price.js");
function total(items) { return items.reduce((s, i) => s + price(i), 0); }
module.exports = { total };

const { sortAsc } = require("../src/sort.js");
const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const cases = [
  [[3, 1, 2], [1, 2, 3]],
  [[-1, -5, 3], [-5, -1, 3]],
  [[10, 9, 2], [2, 9, 10]],
  [[], []]
];
for (const [input, want] of cases) {
  const got = sortAsc(input);
  if (!eq(got, want)) { console.error("FAIL", input, "got", got, "want", want); process.exit(1); }
}
console.log("all pass");

const { maxOf } = require("../src/max.js");
if (maxOf([1, 5, 2]) !== 5) process.exit(1);
if (maxOf([]) !== 0) process.exit(1);
if (maxOf([-3, -1]) !== -1) process.exit(1);
console.log("ok");
